import numpy as np
import time
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    L = fftconvolve(h, h, mode='full')
    L = np.concatenate(([0.0], L, [0.0]))
    l2 = (L[:-1]*L[:-1] + L[:-1]*L[1:] + L[1:]*L[1:]).sum() / 3.0
    m = L.max()
    if m <= 0:
        return -1.0
    return l2 / (s*s*m)


def _peak_feed_indices(h, thresh=0.999, pad=4):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    M = L.max()
    if M <= 0:
        return np.arange(N)
    P = np.nonzero(L >= thresh * M)[0]
    if P.size == 0:
        P = np.array([int(np.argmax(L))])
    parts = []
    for p in P:
        c = p // 2
        lo = max(0, c - pad)
        hi = min(N - 1, c + pad)
        parts.append(np.arange(lo, hi + 1))
    if not parts:
        return np.arange(N)
    return np.unique(np.concatenate(parts))


def _resample(h, N_new):
    N_old = h.size
    if N_new == N_old:
        return h.copy()
    x_old = (np.arange(N_old) + 0.5) / N_old
    x_new = (np.arange(N_new) + 0.5) / N_new
    out = np.interp(x_new, x_old, h)
    return np.clip(out, 0.0, None)


def _coord_descent(h, R_cur, deadline, t0, rng, n_sweeps=2, step0=0.03):
    h = h.copy()
    N = h.size
    if N < 4:
        return h, R_cur
    invphi = (np.sqrt(5.0) - 1.0) / 2.0
    for _ in range(n_sweeps):
        if time.process_time() - t0 > deadline:
            break
        order = rng.permutation(N)
        for i in order:
            if time.process_time() - t0 > deadline:
                break
            i = int(i)
            hi = h.max()
            if hi <= 0:
                continue
            step = step0 * hi
            a, b = -min(h[i], step), step
            c = b - invphi * (b - a)
            d = a + invphi * (b - a)
            trial = h.copy()
            trial[i] = h[i] + c
            fc = _R(trial)
            trial[i] = h[i] + d
            fd = _R(trial)
            for _ in range(16):
                if time.process_time() - t0 > deadline:
                    break
                if fc > fd:
                    b, d, fd = d, c, fc
                    c = b - invphi * (b - a)
                    trial[i] = h[i] + c
                    fc = _R(trial)
                else:
                    a, c, fc = c, d, fd
                    d = a + invphi * (b - a)
                    trial[i] = h[i] + d
                    fd = _R(trial)
            best_x = c if fc > fd else d
            best_f = max(fc, fd)
            if best_f > R_cur:
                h[i] = max(0.0, h[i] + best_x)
                R_cur = best_f
    return h, R_cur


def _pair_swap(h, R_cur, deadline, t0, rng, n_idx=400, lo=0.5, hi=0.5, iters=14):
    h = h.copy()
    N = h.size
    if N < 4:
        return h, R_cur
    invphi = (np.sqrt(5.0) - 1.0) / 2.0
    I = _peak_feed_indices(h, thresh=0.999, pad=4)
    for _ in range(n_idx):
        if time.process_time() - t0 > deadline:
            break
        i = int(I[rng.integers(0, I.size)])
        j = int(rng.integers(0, N))
        if i == j or h.max() <= 0:
            continue

        def eval_t(t):
            trial = h.copy()
            trial[i] = max(0.0, h[i] * np.exp(t))
            trial[j] = max(0.0, h[j] * np.exp(-t))
            if trial.sum() <= 0:
                return -1.0
            return _R(trial)

        a, b = -lo, hi
        c = b - invphi * (b - a)
        d = a + invphi * (b - a)
        fc = eval_t(c); fd = eval_t(d)
        for _ in range(iters):
            if time.process_time() - t0 > deadline:
                break
            if fc > fd:
                b, d, fd = d, c, fc
                c = b - invphi * (b - a)
                fc = eval_t(c)
            else:
                a, c, fc = c, d, fd
                d = a + invphi * (b - a)
                fd = eval_t(d)
        best_t = c if fc > fd else d
        best_f = max(fc, fd)
        if best_f > R_cur:
            h[i] = max(0.0, h[i] * np.exp(best_t))
            h[j] = max(0.0, h[j] * np.exp(-best_t))
            R_cur = best_f
    return h, R_cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5

    def time_left():
        return deadline - (time.process_time() - t0)

    best_h = None
    best_R = -1.0

    def consider(h):
        nonlocal best_h, best_R
        h = np.asarray(h, dtype=float)
        if h.ndim != 1 or h.size == 0 or h.size > 50000:
            return -1.0
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return -1.0
        r = _R(h)
        if r > best_R:
            best_R = r
            best_h = h.copy()
        return r

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0 and np.all(s >= 0):
            consider(s)

    if best_h is None:
        best_h = np.ones(100)
        best_R = _R(best_h)

    # Polish the start shape directly with pair-swaps + coord descent.
    rng = np.random.default_rng(777001)
    h = best_h / best_h.max()
    r = _R(h)
    h, r = _pair_swap(h, r, deadline, t0, rng, n_idx=300)
    consider(h)
    h, r = _coord_descent(h, r, deadline, t0, rng, n_sweeps=1, step0=0.02)
    consider(h)

    # Try resampled variants — a different N can escape local optima.
    base = best_h.copy()
    sizes = [base.size]
    for f in (1.15, 0.87, 1.3, 0.77, 1.5):
        n = int(base.size * f)
        if 8 <= n <= 50000:
            sizes.append(n)
    for N_try in sizes:
        if time_left() <= 1.0:
            break
        h0 = _resample(base, N_try)
        if h0.sum() <= 0:
            continue
        r0 = _R(h0)
        if r0 > 0.99 * best_R:
            sub_deadline = min(deadline, (time.process_time()-t0) + max(1.0, time_left()/len(sizes)))
            rng2 = np.random.default_rng(1000 + N_try)
            hh, rr = _pair_swap(h0, r0, sub_deadline, t0, rng2, n_idx=150)
            consider(hh)
            hh, rr = _coord_descent(hh, rr, sub_deadline, t0, rng2, n_sweeps=1, step0=0.02)
            consider(hh)

    # Final intensive polish on the best shape.
    if time_left() > 0.5:
        rng = np.random.default_rng(424242)
        h = best_h / best_h.max()
        r = best_R
        round_num = 0
        while time_left() > 0.5 and round_num < 6:
            round_num += 1
            h, r = _pair_swap(h, r, deadline, t0, rng, n_idx=200)
            consider(h)
            h, r = _coord_descent(h, r, deadline, t0, rng, n_sweeps=1, step0=0.015)
            consider(h)
            # small kick if stuck
            if round_num >= 2 and time_left() > 1.0:
                kick = h.copy()
                N = kick.size
                idx = _peak_feed_indices(kick, thresh=0.995, pad=3)
                for _ in range(3):
                    i = int(idx[rng.integers(0, idx.size)])
                    kick[i] = max(0.0, kick[i] * np.exp(rng.normal(0, 0.03)))
                if kick.sum() > 0:
                    kick /= kick.max()
                    rk = _R(kick)
                    if rk > r * 0.999:
                        h, r = kick, rk

    out = np.asarray(best_h, dtype=float)
    out = np.clip(out, 0.0, None)
    if out.sum() <= 0:
        out = np.ones(100)
    if out.size > 50000:
        out = out[:50000]
    return out

