def _triple_golden(h, R_cur, deadline, t0, rng, n_trials=120,
                   peak_thresh=0.999, pad=3, span=0.35, iters=10):
    """Coordinate ascent over a triple (i peak-feeding, j, k) using log-param
    with two coupled parameters (a,b): h[i]*=e^a, h[j]*=e^b, h[k]*=e^{-a-b}."""
