            consider(hsm)
        if time_left() > 0.8:
            sub = min(deadline, (process_time := time.process_time()) - t0 + max(1.5, time_left() * 0.55))
            hpk, rpk = _peak_pair_joint(best_h.copy(), best_R, sub, t0, rng,
                                        n_trials=300, thresh=0.99995, pad=5,
                                        lo=0.5, hi=0.5, iters=16)
            consider(hpk)
        gain = best_R - R_before
        print(f"alt round={rnd} R={best_R:.9f} gain={gain:.2e} t={time.process_time()-t0:.1f}")
        if gain < 1e-9 and rnd > 6:
            break

    print(f"final R={best_R:.9f} t={time.process_time()-t0:.1f}")

    out = np.asarray(best_h, dtype=float)
    out = np.clip(out, 0.0, None)
    if out.sum() <= 0:
        out = np.ones(100)
    if out.size > 50000:
        out = out[:50000]
    return out

import numpy as np
import time
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    L = fftconvolve(h, h, mode='full')
    L = np.concatenate(([0.0], L, [0.0]))
    l2 = (L[:-1]*L[:-1] + L[:-1]*L[1:] + L[1:]*L[1:]).sum() / 3.0
    m = L.max()
    if m <= 0:
        return -1.0
    return l2 / (s*s*m)


def _R_grad_z(z, eps):
    h = np.exp(z) - eps
    h = np.clip(h, 0.0, None)
    s = h.sum()
    if s <= 0:
        return 1e6, np.zeros_like(z)
    L = fftconvolve(h, h, mode='full')
    L = np.concatenate(([0.0], L, [0.0]))
    Lp = L[1:]; Lm = L[:-1]
    q = Lm*Lm + Lm*Lp + Lp*Lp
    l2 = q.sum() / 3.0
    m = L.max()
    if m <= 0:
        return 1e6, np.zeros_like(z)
    R = l2 / (s*s*m)
    dq = np.zeros(L.size)
    dq[:-1] += (2.0*Lm + Lp)
    dq[1:] += (Lm + 2.0*Lp)
    dq /= 3.0
    am = int(np.argmax(L))
    dR_dL = dq / (s*s*m)
    dR_dL[am] -= l2 / (s*s*m*m)
    dR_ds = -2.0 * l2 / (s*s*s*m)
    g = dR_dL[1:-1]
    N = h.size
    corr = fftconvolve(g, h[::-1], mode='full')
    dR_dh = 2.0 * corr[N-1:2*N-1] + dR_ds
    dR_dz = dR_dh * (h + eps)
    return -R, -dR_dz


def _peak_feed_indices(h, thresh=0.999, pad=4):
    N = h.size
    L = fftconvolve(h, h, mode='full')
    M = L.max()
    if M <= 0:
        return np.arange(N)
    P = np.nonzero(L >= thresh * M)[0]
    if P.size == 0:
        P = np.array([int(np.argmax(L))])
    parts = []
    for p in P:
        c = p // 2
        parts.append(np.arange(max(0, c - pad), min(N - 1, c + pad) + 1))
    return np.unique(np.concatenate(parts)) if parts else np.arange(N)


def _resample(h, N_new):
    N_old = h.size
    if N_new == N_old:
        return h.copy()
    x_old = (np.arange(N_old) + 0.5) / N_old
    x_new = (np.arange(N_new) + 0.5) / N_new
    return np.clip(np.interp(x_new, x_old, h), 0.0, None)


def _hill_climb(h, R_cur, deadline, t0, rng, max_evals=100000):
    h = h.copy(); N = h.size
    if N < 4:
        return h, R_cur
    I = _peak_feed_indices(h, pad=4)
    centers = I.astype(float) if I.size else np.arange(N, dtype=float)
    evals = 0
    while evals < max_evals:
        if time.process_time() - t0 > deadline:
            break
        scale = np.exp(rng.uniform(np.log(3e-4), np.log(0.03)))
        blen = max(1, int(round(N / 12)))
        trial = h.copy()
        for _ in range(3):
            if rng.random() < 0.7 and centers.size > 0:
                c = centers[rng.integers(0, centers.size)]
                st = int(c) - blen // 2 + rng.integers(-blen, blen + 1)
            else:
                st = rng.integers(0, N)
            st = int(np.clip(st, 0, N - 1))
            end = min(N, st + blen)
            if end <= st:
                continue
            amp = scale * h.max() * rng.normal()
            x = np.linspace(-1, 1, end - st)
            bump = np.exp(-3.0 * x * x)
            trial[st:end] = np.clip(trial[st:end] + amp * bump, 0.0, None)
        if trial.sum() <= 0:
            continue
        r = _R(trial); evals += 1
        if r > R_cur:
            h = trial; R_cur = r
            I = _peak_feed_indices(h, pad=4)
            centers = I.astype(float) if I.size else np.arange(N, dtype=float)
    return h, R_cur


def _pair_golden(h, R_cur, deadline, t0, rng, n_idx=400, iters=14):
    h = h.copy(); N = h.size
    if N < 4:
        return h, R_cur
    invphi = (np.sqrt(5.0) - 1.0) / 2.0
    I = _peak_feed_indices(h, pad=4)
    for _ in range(n_idx):
        if time.process_time() - t0 > deadline:
            break
        i = int(I[rng.integers(0, I.size)])
        j = int(rng.integers(0, N))
        if i == j or h.max() <= 0:
            continue
        def eval_t(t):
            trial = h.copy()
            trial[i] = max(0.0, h[i] * np.exp(t))
            trial[j] = max(0.0, h[j] * np.exp(-t))
            if trial.sum() <= 0:
                return -1.0
            return _R(trial)
        a, b = -0.6, 0.6
        c = b - invphi * (b - a); d = a + invphi * (b - a)
        fc = eval_t(c); fd = eval_t(d)
        for _ in range(iters):
            if time.process_time() - t0 > deadline:
                break
            if fc > fd:
                b, d, fd = d, c, fc
                c = b - invphi * (b - a); fc = eval_t(c)
            else:
                a, c, fc = c, d, fd
                d = a + invphi * (b - a); fd = eval_t(d)
        best_t = c if fc > fd else d
        best_f = max(fc, fd)
        if best_f > R_cur:
            h[i] = max(0.0, h[i] * np.exp(best_t))
            h[j] = max(0.0, h[j] * np.exp(-best_t))
            R_cur = best_f
    return h, R_cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5

    def time_left():
        return deadline - (time.process_time() - t0)

    best_h = None; best_R = -1.0

    def consider(h):
        nonlocal best_h, best_R
        h = np.asarray(h, dtype=float)
        if h.ndim != 1 or h.size == 0 or h.size > 50000:
            return -1.0
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return -1.0
        r = _R(h)
        if r > best_R:
            best_R = r; best_h = h.copy()
        return r

    if start is not None:
        consider(start)
    if best_h is None:
        best_h = np.ones(100); best_R = _R(best_h)

    print(f"start R={best_R:.9f} N={best_h.size}")

    eps = 1e-4
    rng = np.random.default_rng(20240)

    def lbfgs(h, R_cur, maxiter=800):
        h = np.asarray(h, dtype=float)
        if h.size < 4 or h.sum() <= 0:
            return h, R_cur
        z0 = np.log(h + eps)
        best = {'R': R_cur, 'h': h.copy()}

        def neg_obj(z):
            if time.process_time() - t0 > deadline - 0.2:
                raise TimeoutError
            hh = np.clip(np.exp(z) - eps, 0.0, None)
            r, g = _R_grad_z(z, eps)
            if -r > best['R']:
                best['R'] = -r; best['h'] = hh.copy()
            return r, g

        try:
            minimize(neg_obj, z0, jac=True, method='L-BFGS-B',
                     options={'maxiter': maxiter, 'maxfun': 2*maxiter,
                              'ftol': 1e-16, 'gtol': 1e-14, 'maxls': 50})
        except Exception:
            pass
        return best['h'], best['R']

    phase = 0
    while time_left() > 1.0:
        phase += 1
        hl, rl = lbfgs(best_h.copy(), best_R, maxiter=600)
        consider(hl)
        print(f"lbfgs#{phase} R={best_R:.9f} N={best_h.size} t={time.process_time()-t0:.1f}")
        if time_left() <= 1.0:
            break

        if best_h.size < 40000 and time_left() > 4.0:
            s2 = np.asarray(best_h, dtype=float)
            sym2 = 0.5 * (s2 + s2[::-1])
            h2 = np.repeat(sym2, 2)
            if h2.max() > 0:
                h2 = h2 / h2.max()
            if _R(h2) > best_R - 1e-6:
                consider(h2)
                print(f"split R={best_R:.9f} N={best_h.size} t={time.process_time()-t0:.1f}")

        if time_left() > 5.0:
            hh, rr = _hill_climb(best_h, best_R, deadline - 3.0, t0, rng, max_evals=20000)
            consider(hh)
        if time_left() > 4.0:
            hh, rr = _pair_golden(best_h, best_R, deadline - 2.0, t0, rng, n_idx=300)
            consider(hh)

    # Final polish: short LBFGS with remaining time on current best.
    if time_left() > 0.5:
        hl, rl = lbfgs(best_h.copy(), best_R, maxiter=300)
        consider(hl)
        print(f"final R={best_R:.9f} N={best_h.size} t={time.process_time()-t0:.1f}")

    out = np.asarray(best_h, dtype=float)
    out = np.clip(out, 0.0, None)
    if out.sum() <= 0:
        out = np.ones(100)
    if out.size > 50000:
        out = out[:50000]
    return out
